import random
import string
from typing import List

# Generator for UTF-8 Markdown text that aims to exercise many cmark features
# while remaining valid/parseable Markdown. Size limited <= 4096 bytes.

MAX_BYTES = 4096

def _rand(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)

def _choice(r: random.Random, seq):
    return seq[r.randrange(len(seq))]

def _weighted_choice(r: random.Random, items):
    # items = [(value, weight), ...]
    total = sum(w for _, w in items)
    x = r.random() * total
    acc = 0.0
    for v, w in items:
        acc += w
        if x <= acc:
            return v
    return items[-1][0]

def _rand_word(r: random.Random) -> str:
    length = _rand(r, 2, 10)
    letters = string.ascii_letters
    return ''.join(r.choice(letters) for _ in range(length))

def _rand_sentence(r: random.Random, max_words=12) -> str:
    n = _rand(r, 3, max_words)
    words = []
    for _ in range(n):
        if r.random() < 0.12:
            # include punctuation token
            words.append(_choice(r, ["--", "…", "&", "*", "_", "~"]))
        else:
            words.append(_rand_word(r))
    s = ' '.join(words)
    if r.random() < 0.2:
        s += _choice(r, [".", "!", "?", "..."])
    return s

def _rand_code_fence(r: random.Random) -> str:
    fence = _choice(r, ["```", "~~~"])
    info = ""
    if r.random() < 0.7:
        # common info strings / languages
        info = _choice(r, ["", "python", "c", "cpp", "json", "markdown", "sh", "html"]) \
               + (" " + _rand_word(r) if r.random() < 0.3 else "")
    lines = [_rand_sentence(r, 8) for _ in range(_rand(r, 1, 5))]
    # include backticks inside as valid content sometimes
    if r.random() < 0.3:
        lines.insert(_rand(r, 0, len(lines)), "print(`nested`)")
    body = "\n".join(lines)
    return f"{fence}{(' ' + info) if info else ''}\n{body}\n{fence}\n"

def _rand_inline_emphasis(r: random.Random) -> str:
    text = _rand_sentence(r, 8)
    style = _choice(r, ["*", "_", "**", "__", "~~"])  # italics, bold, strikethrough
    return f"{style}{text}{style}"

def _rand_link(r: random.Random, image=False) -> str:
    label = _rand_sentence(r, 6)
    # sometimes include nested formatting in label
    if r.random() < 0.3:
        label = label + " " + _rand_inline_emphasis(r)
    scheme = _choice(r, ["http", "https", "mailto", "ftp"]) if r.random() < 0.9 else _rand_word(r)
    host = _choice(r, ["example.com", "test.local", "localhost", "例子.测试"])  # unicode domain to test UTF-8
    path = "/" + "/".join(_rand_word(r).lower() for _ in range(_rand(r, 0, 3)))
    if r.random() < 0.3:
        path += "?" + "&".join(f"{_rand_word(r).lower()}={_rand_word(r).lower()}" for _ in range(_rand(r,1,3)))
    url = f"{scheme}://{host}{path}" if scheme != "mailto" else f"mailto:{_rand_word(r).lower()}@{host}"
    title = ''
    if r.random() < 0.4:
        q = _choice(r, ['"', "'"])
        title = f" {q}{_rand_sentence(r, 6)}{q}"
    bang = "!" if image else ""
    return f"{bang}[{label}]({url}{title})"

def _rand_heading(r: random.Random) -> str:
    level = _rand(r, 1, 6)
    prefix = "#" * level
    text = _rand_sentence(r, 10)
    if r.random() < 0.3:
        text += " " + _rand_link(r)
    return f"{prefix} {text}\n"

def _rand_list_block(r: random.Random, ordered: bool) -> str:
    n = _rand(r, 1, 6)
    items: List[str] = []
    start = _rand(r, 1, 5) if ordered and r.random() < 0.5 else 1
    # delimiter styles for ordered lists
    delim = _choice(r, [".", ")"]) if ordered else None
    tight = r.random() < 0.5
    for i in range(n):
        if ordered:
            num = start + i
            marker = f"{num}{delim} "
        else:
            marker = _choice(r, ["- ", "* ", "+ "])
        content_parts = []
        # first line
        content_parts.append(_rand_sentence(r, 10))
        # nested content sometimes
        if r.random() < 0.35:
            nested_kind = _choice(r, ["para", "list", "code"])
            if nested_kind == "para":
                content_parts.append("\n\n    " + _rand_sentence(r, 10))
            elif nested_kind == "list":
                sub = _rand_list_block(r, ordered=bool(_rand(r,0,1)))
                # indent nested list by 4 spaces
                sub = "\n" + "\n".join("    " + ln for ln in sub.strip("\n").splitlines()) + "\n"
                content_parts.append(sub)
            else:  # code
                code = "\n" + "\n".join("    " + _rand_sentence(r, 6) for _ in range(_rand(r,1,3)))
                content_parts.append(code)
        item = marker + content_parts[0]
        tail = ''.join(content_parts[1:])
        items.append(item + tail)
        if not tight:
            items.append("")  # blank line between loose items
    body = "\n".join(items).rstrip() + "\n"
    return body

def _rand_blockquote(r: random.Random) -> str:
    lines = []
    for _ in range(_rand(r, 1, 4)):
        kind = _weighted_choice(r, [("text", 5), ("list", 2), ("code", 2), ("quote", 1)])
        if kind == "text":
            lines.append("> " + _rand_sentence(r, 12))
        elif kind == "list":
            lst = _rand_list_block(r, ordered=bool(_rand(r,0,1)))
            for ln in lst.strip("\n").splitlines():
                lines.append("> " + ln)
        elif kind == "code":
            cf = _rand_code_fence(r).strip("\n").splitlines()
            for ln in cf:
                lines.append("> " + ln)
        else:
            # nested quote
            lines.append("> > " + _rand_sentence(r, 10))
    return "\n".join(lines) + "\n"

def _rand_html_block(r: random.Random) -> str:
    tag = _choice(r, ["div", "span", "section", "script", "style"])  # some raw HTML
    attrs = ''
    if r.random() < 0.5:
        attrs = f" id=\"{_rand_word(r).lower()}\" class=\"{_rand_word(r).lower()}\""
    if tag in ("script", "style"):
        content = _rand_sentence(r, 6)
    else:
        content = _rand_sentence(r, 10) + (" " + _rand_link(r) if r.random() < 0.3 else "")
    return f"<{tag}{attrs}>{content}</{tag}>\n"

def _rand_table_like(r: random.Random) -> str:
    # GitHub-flavored tables are not standard CommonMark, but cmark with extensions can parse.
    # We include a simple variant; if extension disabled, it will be treated as text.
    cols = _rand(r, 2, 5)
    headers = [ _rand_word(r).capitalize() for _ in range(cols) ]
    aligns = []
    for _ in range(cols):
        aligns.append(_choice(r, [":---", ":---:", "---:", "---"]))
    rows = []
    for _ in range(_rand(r, 1, 4)):
        rows.append(" | ".join(_rand_sentence(r, 5) for _ in range(cols)))
    return (
        " | ".join(headers) + "\n" +
        " | ".join(aligns) + "\n" +
        "\n".join(rows) + "\n"
    )

def _rand_paragraph(r: random.Random) -> str:
    parts = []
    for _ in range(_rand(r, 1, 4)):
        kind = _weighted_choice(r, [("plain", 5), ("em", 2), ("code", 2), ("link", 3), ("image", 1)])
        if kind == "plain":
            parts.append(_rand_sentence(r, 12))
        elif kind == "em":
            parts.append(_rand_inline_emphasis(r))
        elif kind == "code":
            code = _choice(r, ["`inline`", "`` code with `backtick` ``"])
            parts.append(code)
        elif kind == "link":
            parts.append(_rand_link(r, image=False))
        else:
            parts.append(_rand_link(r, image=True))
    return " ".join(parts) + "\n"

def _assemble_document(r: random.Random) -> str:
    blocks = []
    # Choose a mixture of block types
    num_blocks = _rand(r, 5, 20)
    for _ in range(num_blocks):
        block = _weighted_choice(r, [
            ("heading", 3),
            ("paragraph", 6),
            ("list_bullet", 4),
            ("list_ordered", 3),
            ("code_fence", 3),
            ("blockquote", 2),
            ("html", 2),
            ("table", 1),
            ("hr", 1)
        ])
        if block == "heading":
            blocks.append(_rand_heading(r))
        elif block == "paragraph":
            blocks.append(_rand_paragraph(r) + ("\n" if r.random() < 0.5 else ""))
        elif block == "list_bullet":
            blocks.append(_rand_list_block(r, ordered=False) + ("\n" if r.random() < 0.5 else ""))
        elif block == "list_ordered":
            blocks.append(_rand_list_block(r, ordered=True) + ("\n" if r.random() < 0.5 else ""))
        elif block == "code_fence":
            blocks.append(_rand_code_fence(r) + ("\n" if r.random() < 0.4 else ""))
        elif block == "blockquote":
            blocks.append(_rand_blockquote(r) + ("\n" if r.random() < 0.4 else ""))
        elif block == "html":
            blocks.append(_rand_html_block(r) + ("\n" if r.random() < 0.5 else ""))
        elif block == "table":
            blocks.append(_rand_table_like(r) + ("\n" if r.random() < 0.5 else ""))
        else:  # hr
            hr = _choice(r, ["---", "***", "___"]) + "\n\n"
            blocks.append(hr)
    doc = "".join(blocks)
    # Optionally add reference link definitions at end
    if r.random() < 0.4:
        for _ in range(_rand(r, 1, 4)):
            ref = _rand_word(r).lower()
            url = f"https://example.com/{_rand_word(r).lower()}"
            title = _choice(r, ["", f' "{_rand_sentence(r,6)}"', f" '{_rand_sentence(r,6)}'"])
            doc += f"[{ref}]: {url}{title}\n"
    return doc

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # With some probability, emit a focused construct to stress a particular API path
    mode = _weighted_choice(r, [
        ("full", 6),
        ("large_list", 2),
        ("deep_quote", 1),
        ("code_only", 1),
        ("headers", 2)
    ])

    if mode == "large_list":
        # Big ordered list with start offset and mixed delimiters (well-formed per item)
        start = _rand(r, 1, 50)
        n = _rand(r, 20, 80)
        delim = _choice(r, [".", ")"])
        lines = []
        for i in range(n):
            lines.append(f"{start+i}{delim} " + _rand_sentence(r, 10))
            if r.random() < 0.2:
                lines.append("")
        text = "\n".join(lines) + "\n"
    elif mode == "deep_quote":
        depth = _rand(r, 5, 16)
        para = _rand_sentence(r, 12)
        text = ("> " * depth) + para + "\n\n" + _rand_paragraph(r)
    elif mode == "code_only":
        parts = [_rand_code_fence(r) for _ in range(_rand(r, 2, 6))]
        text = "\n".join(parts)
    elif mode == "headers":
        parts = [_rand_heading(r) for _ in range(_rand(r, 6, 20))]
        text = "\n".join(parts) + "\n" + _rand_paragraph(r)
    else:
        text = _assemble_document(r)

    # Ensure within byte limit; trim at UTF-8 boundary by using encode and slicing
    data = text.encode('utf-8', errors='strict')
    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]
        # Best effort to avoid cutting a multi-byte sequence: decode with ignore and re-encode
        data = data.decode('utf-8', errors='ignore').encode('utf-8')
    return data
